import { useQuery } from '@tanstack/react-query';

export interface MonthYearCount {
  monthYear: string;
  count: number;
}

const getMonthsYears = async (): Promise<MonthYearCount[]> => {
  const response = await fetch('/api/bluebird/months-years');
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const monthsYears: MonthYearCount[] = await response.json();
  return monthsYears;
};

export function useBluebirdMonthsYears() {
  return useQuery<MonthYearCount[]>({
    queryKey: ['monthsYears'],
    queryFn: getMonthsYears
  });
}
